contract InvMutTest {
    C c;
    address payable deployer;
    constructor(C _c) {
        c = _c;
        deployer = payable(address(this));
    }

    // single public test function taking an address to act as the caller and an amount of wei to fund c
    function run(address caller, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund c");
        // fund the target contract with ETH so selfdestruct has value to transfer
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // call as owner (this contract is the owner since constructor of sGuardPlus set owner to deployer of C,
        // and the problem statement ensures InvMutTest deployed C; msg.sender for calls from this contract is InvMutTest)
        bool ownerReverted;
        try c.sudicideAnyone() {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        // Record balances after owner's attempt
        uint256 balanceC_after = address(c).balance;
        uint256 balanceThis_after = address(this).balance;

        // Now attempt call as non-owner by using a low-level call with a different msg.sender cannot be simulated here because
        // the checker runs this single transaction; however we can reason about non-owner by deploying a minimal proxy would break constraints.
        // Instead we assert the general rule: if the owner call did not revert, then contract balance must be zero and this contract gained fundAmount;
        // if the owner call reverted then neither balances changed (i.e., c keeps its funds and this contract balance unchanged except for funding).

        // compute expected relations
        // If owner call succeeded: c balance becomes 0 and this contract balance increases by fundAmount
        // If owner call reverted: c balance remains fundAmount and this contract balance is reduced by fundAmount (from funding)

        assert(
            (!ownerReverted && balanceC_after == 0 && balanceThis_after >= address(this).balance - 0 && balanceThis_after >= fundAmount - 0) ||
            (ownerReverted && balanceC_after == fundAmount)
        );
    }

    receive() external payable {}
}

