contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public entry performing the property check
    function run(address caller, uint sendValue) public payable {
        require(address(this).balance >= sendValue);
        // Capture contract balance before call
        uint balBefore = address(c).balance;
        // Attempt call as non-owner: since InvMutTest deployed C, this contract is the owner.
        // So to simulate non-owner we perform a low-level call from this contract but specify target to forward to C via delegatecall is not allowed.
        // Instead, we check two cases based on the provided caller flag: if caller == address(this) we act as owner; otherwise we act as non-owner by using a helper contract created inline.
        bool reverted;

        if (caller == address(this)) {
            // Owner case: calling sudicideAnyone should succeed and selfdestruct, transferring balance to msg.sender (InvMutTest)
            // Call and catch revert
            try c.sudicideAnyone{value: sendValue}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After successful owner call, contract c should have been selfdestructed, so its balance should be 0 and InvMutTest should have received its previous balance + sendValue
            // But since we cannot directly observe internal selfdestruct other than balance, assert accordingly below
        } else {
            // Non-owner case: deploy a transient helper that will call c.sudicideAnyone() from a different address
            Helper h = new Helper();
            // Ensure helper has funds if needed
            if (sendValue > 0) {
                // transfer ETH to helper
                (bool t,) = address(h).call{value: sendValue}("");
                require(t);
            }
            try h.callSudicide(address(c)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balAfter = address(c).balance;
        // General rule: if non-owner attempted the call then it must have reverted and c's balance unchanged; if owner attempted, it must not revert and c's balance becomes 0 (selfdestruct sends to caller)
        assert((caller != address(this) && reverted && balAfter == balBefore) || (caller == address(this) && !reverted && balAfter == 0));
    }

    receive() external payable {}
}

contract Helper {
    constructor() payable {}
    function callSudicide(address target) public payable {
        // Forward call as this different caller
        C(target).sudicideAnyone{value: msg.value}();
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // callerIsOwner: when true, the call is made from this contract (the owner); when false, a helper contract (different address) makes the call.
    // sendValue: amount of wei forwarded to the helper when callerIsOwner==false (to allow transferring funds if desired). Must be supplied by the caller and this contract must hold >= sendValue when forwarding.
    function run(bool callerIsOwner, uint sendValue) public payable {
        // If we will forward ETH to helper, ensure this contract has it
        if (!callerIsOwner) {
            require(address(this).balance >= sendValue);
        }

        // Record balance before any actions
        uint balBefore = address(c).balance;

        bool reverted;

        if (callerIsOwner) {
            // Owner case: call sudicideAnyone from this contract (which deployed C and is owner)
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-owner case: deploy a helper contract and have it call sudicideAnyone
            Helper h = new Helper{value: 0}();
            // If needed, fund the helper so it can send value with the call
            if (sendValue > 0) {
                (bool sent,) = address(h).call{value: sendValue}("");
                require(sent);
            }
            try h.callSudicide(address(c)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balAfter = address(c).balance;

        // Assert the general rule:
        // - If non-owner attempted the call, it must have reverted and c's balance unchanged.
        // - If owner attempted the call, it must not have reverted and c's balance must be 0 (selfdestruct transfers funds to caller).
        assert((!callerIsOwner && reverted && balAfter == balBefore) || (callerIsOwner && !reverted && balAfter == 0));
    }

    receive() external payable {}
}

