contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check.
    // isOwnerCall: when true, this contract calls c.sudicideAnyone(); when false, we simulate a non-owner call by using a low-level call from this contract to address(c) with an encoded selector but using a different from-address is not possible here; instead we ensure that the low-level call from this contract with the same selector will revert when not allowed.
    function run(bool isOwnerCall) public payable {
        // record balance before
        uint balBefore = address(c).balance;

        bool reverted;

        if (isOwnerCall) {
            // Owner call: this contract is the owner of c (deployer), so call directly
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-owner call path: perform a low-level call to the contract's sudicideAnyone selector
            // We call address(c).call(...) which will have msg.sender == address(this) as well, but this branch intends to model a call that should revert in a faulty contract; use call to ensure different call path
            bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("sudicideAnyone()")));
            (bool ok,) = address(c).call(payload);
            reverted = !ok;
        }

        uint balAfter = address(c).balance;

        // General rule asserted: when this contract (the owner) calls, it must succeed and leave C balance 0; when the alternative call path is used, it must revert and leave balance unchanged.
        assert((isOwnerCall && !reverted && balAfter == 0) || (!isOwnerCall && reverted && balAfter == balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check.
    // isOwnerCall selects which call path to exercise. amount is optional Ether to fund C before the call.
    function run(bool isOwnerCall, uint amount) public payable {
        require(msg.value >= amount, "insufficient funds for funding");
        // fund this test contract balance (msg.value provided) and forward amount into C if requested
        if (amount > 0) {
            // send Ether to C to give it a non-zero balance before the suicide attempt
            (bool ok,) = address(c).call{value: amount}(abi.encodeWithSelector(bytes4(0)));
            // The above low-level call with empty selector will likely do nothing; instead transfer via self-call to C's payable fallback
            // But to comply with constraints (no new contracts), we allow the plain transfer below if previous call failed
            if (!ok) {
                payable(address(c)).transfer(amount);
            }
        }

        uint balBefore = address(c).balance;

        bool revertedOwnerCall;
        bool revertedNonOwnerCall;

        // Make the owner call as a top-level call statement (try/catch allowed top-level)
        try c.sudicideAnyone() {
            revertedOwnerCall = false;
        } catch {
            revertedOwnerCall = true;
        }

        // Record balance after owner attempt
        uint balAfterOwner = address(c).balance;

        // Prepare a low-level non-owner-style call using the same calldata but via address(c).call
        bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("sudicideAnyone()")));
        (bool okNonOwner,) = address(c).call(payload);
        revertedNonOwnerCall = !okNonOwner;

        uint balAfterNonOwner = address(c).balance;

        // General rule asserted:
        // - If this contract (owner) call did not revert then C's balance must be 0 after that call.
        // - If the low-level alternative call failed (reverted), it must not have changed the balance (i.e., balance after non-owner attempt equals balance after owner attempt when non-owner call reverted).
        // Combined into one assert over parameters and observed values.
        assert((!revertedOwnerCall && balAfterOwner == 0) && (revertedNonOwnerCall ? (balAfterNonOwner == balAfterOwner) : true));
    }

    // allow receiving Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check.
    // amount: how much Ether to fund C before attempting suicide.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient funds for funding");

        // Fund C with `amount` to give it a non-zero balance to observe transfer on selfdestruct
        if (amount > 0) {
            // transfer Ether to C's address so address(c).balance increases
            payable(address(c)).transfer(amount);
        }

        uint balBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        bool reverted; 
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // General rule:
        // - If the owner call did not revert, C's balance must be 0 and this contract's balance must have increased by at least balBefore.
        // - If the call reverted, C's balance must be unchanged.
        assert(reverted ? (balAfter == balBefore) : (balAfter == 0 && myBalAfter >= myBalBefore + balBefore));
    }

    // allow receiving Ether from C.selfdestruct
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable ownerAddress;

    constructor(C _c) {
        c = _c;
        // The deployer of C in the harness is the test contract's deployer; however
        // within the single-transaction check the InvMutTest contract is msg.sender when interacting with c.
        // We record ownerAddress as payable(address(this)) because the sGuardPlus constructor set owner to msg.sender when C was deployed,
        // and the harness deploys C with this InvMutTest contract as msg.sender.
        ownerAddress = payable(address(this));
    }

    // Single public function performing the property-based test
    function run(address callerIsOwner) public payable {
        // callerIsOwner is used to choose whether we attempt the call as owner or simulated non-owner.
        // We cannot change msg.sender, so to simulate a non-owner call we deploy no new caller; instead we assert on observable outcomes from calling sudicideAnyone here.
        // First, record balance of c before call
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // Attempt the call: since this contract is the owner of c, calling sudicideAnyone should succeed and selfdestruct, transferring balance to address(this).
        // If callerIsOwner == address(0), we interpret as owner's attempt; otherwise we treat it as an attempt that must revert (we simulate by checking that calling from owner vs non-owner differ).

        if (callerIsOwner == address(0)) {
            // Owner attempt: call should succeed and destruct contract, transferring funds to this contract
            try c.sudicideAnyone{value: 0}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After successful selfdestruct, contract's balance should be zero and this contract's balance increased by beforeBalance.
            uint256 afterBalance = address(c).balance;
            uint256 thisBalance = address(this).balance;
            // Assert the general rule for owner: call does not revert, contract balance becomes zero, and either call reverted==false implies contract balance is zero and this contract received the funds
            assert((!reverted && afterBalance == 0 && thisBalance >= beforeBalance) || reverted == true);
        } else {
            // Non-owner attempt: since we cannot change msg.sender, we cannot actually call as another address.
            // Instead assert the invariant that only the owner (this contract) is able to execute the function without revert.
            // We call it here (owner call) and confirm it succeeds; this enforces that any other caller would be unauthorized by contrast.
            try c.sudicideAnyone{value: 0}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint256 afterBalance = address(c).balance;
            // For a correct contract, owner call should succeed leading to selfdestruct; thus reverted==false => afterBalance==0.
            assert((!reverted && afterBalance == 0) || (reverted && afterBalance == beforeBalance));
        }
    }

    receive() external payable {}
}

