contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no precondition
        // record balances before the call
        uint256 beforeCaller = address(this).balance;
        uint256 beforeC = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: either it reverted (no state change), or caller received the funds from c (all of c's previous balance)
        // If reverted, nothing guaranteed about balances beyond that the call reverted.
        // If not reverted, then C was selfdestructed sending its balance to msg.sender (this contract), so
        // this contract's balance must have increased by exactly beforeC and C's balance must be zero.
        assert(
            reverted || (address(c).balance == 0 && address(this).balance == beforeCaller + beforeC)
        );
    }
    // allow receiving Ether forwarded by selfdestruct
    receive() external payable {}
}

